#pragma once
#include "ksNoteOnStateTask.h"
#include "ksNoteOffStateTask.h"
#include "ksPartControlTasks.h"
#include "ksNativeKeyService.h"
#include "ksNativeArpResetService.h"
#include "ksNativeVoiceReleaseService.h"
#include "ksInternalKeyOutputService.h"
#include <optional>
#include <type_traits>
namespace ks {
class NativeNoteStateService final {
public:
 enum class Kind{On,Off};enum class Component{State,Lookup,Keys,ArpReset,VoiceRelease,InternalRelease};
 struct Input{uint16_t noteVelocity=0;uint32_t stream=0;};struct Effect{bool read=false,write=false;};
 struct Summary{Kind kind=Kind::On;Input input{};uint8_t part=0;bool appended=false,activity=false,heldScan=false,released=false;std::optional<NativeArpResetService>arp;std::optional<NativeKeyService>held;};
 explicit NativeNoteStateService(Kind k):NativeNoteStateService(k,Input{}){}NativeNoteStateService(Kind k,Input i):kind_(k){summary_.kind=k;summary_.input=i;if(k==Kind::On)on_.emplace();else off_.emplace();}
 Kind kind()const{return kind_;}bool complete()const{return kind_==Kind::On?on_->complete():off_->complete();}bool critical()const{return component_==Component::InternalRelease&&internal_&&internal_->critical();}Component component()const{return component_;}uint32_t components()const{return components_;}const Effect&effect()const{return effect_;}const Summary&summary()const{return summary_;}
 template<class T>const T*task()const{if constexpr(std::is_same_v<T,NoteOnStateTask>)return component_==Component::State&&on_?&*on_:nullptr;else if constexpr(std::is_same_v<T,NoteOffStateTask>)return component_==Component::State&&off_?&*off_:nullptr;else if constexpr(std::is_same_v<T,PartLookupTask>){if(component_==Component::Lookup&&lookup_)return &*lookup_;return nested<T>();}else if constexpr(std::is_same_v<T,NativeKeyService>)return component_==Component::Keys&&keys_?&*keys_:nullptr;else if constexpr(std::is_same_v<T,NativeArpResetService>)return component_==Component::ArpReset&&arp_?&*arp_:nullptr;else if constexpr(std::is_same_v<T,NativeVoiceReleaseService>)return component_==Component::VoiceRelease&&voice_?&*voice_:nullptr;else if constexpr(std::is_same_v<T,InternalKeyOutputService>)return component_==Component::InternalRelease&&internal_?&*internal_:nullptr;else return nested<T>();}
 unsigned nextClocks(int previous=-1)const{if(complete())return 0;switch(component_){case Component::State:if(on_)return on_->nextClocks(on_->bytePublication()?byteClock(base()+on_->publicationOffset(),previous):3);return off_->nextClocks(off_->publication()?byteClock(base()+off_->publicationOffset(),previous):3);case Component::Lookup:return lookup_->stage()==PartLookupTask::Stage::Complete?17:lookup_->nextClocks();case Component::Keys:return keys_->nextClocks(previous);case Component::ArpReset:return arp_->nextClocks(previous);case Component::VoiceRelease:return voice_->nextClocks(previous);case Component::InternalRelease:return internal_->nextClocks(previous);}return 0;}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;effect_={};
  if(component_==Component::Lookup){if(lookup_->stage()==PartLookupTask::Stage::Complete){summary_.part=lookup_->index();if(on_)on_->resumePart(summary_.part);else if(off_->awaitingPart())off_->resumePart(summary_.part);else off_->resumePhysicalPart(summary_.part);lookup_.reset();effect_.read=true;select(Component::State);}else lookup_->advanceBefore(cost,[&](auto){return read(0x17526,cost);});return cost;}
  if(component_==Component::Keys){keys_->advanceBefore(cost,read,write,previous);effect_={keys_->effect().read,keys_->effect().write};if(keys_->complete()){const auto&s=keys_->summary();if(on_){summary_.activity=s.activity!=0;on_->resumeActivity(s.activity);}else if(off_->awaitingCompact()){summary_.part=s.part;off_->resumeCompact(s.part);}else{summary_.heldScan=true;summary_.held=keys_;summary_.part=s.part;off_->resumeHeld(s.activity!=0,s.part);}keys_.reset();select(Component::State);}return cost;}
  if(component_==Component::ArpReset){arp_->advanceBefore(cost,read,write,previous);effect_={arp_->effect().read,arp_->effect().write};if(arp_->complete()){summary_.arp=arp_;arp_.reset();on_->resumeMonoReset();select(Component::State);}return cost;}
  if(component_==Component::VoiceRelease){voice_->advanceBefore(cost,read,write,previous);effect_={voice_->effect().read,voice_->effect().write};if(voice_->complete()){voice_.reset();off_->resumeRelease();select(Component::State);}return cost;}
  if(component_==Component::InternalRelease){internal_->advanceBefore(cost,read,write,previous);effect_={internal_->effect().read,internal_->effect().write};if(internal_->complete()){internal_.reset();off_->resumeMonoReset();select(Component::State);}return cost;}
  if(on_){using T=NoteOnStateTask;using S=T::Stage;const auto stage=on_->stage();on_->advanceBefore(cost,[&](T::Input f,unsigned at)->uint32_t{switch(f){case T::Input::MidiWord:return summary_.input.noteVelocity;case T::Input::Note:return uint8_t(summary_.input.noteVelocity);case T::Input::Velocity:return uint8_t(summary_.input.noteVelocity>>8);default:return read(base()+at,cost-((f==T::Input::PhysicalByte||f==T::Input::HeldByte)?byteClock(base()+at,previous):0));}},[&](unsigned at,uint32_t v,unsigned width){if(width==2){write(base()+at,uint8_t(v>>8),cost);write(base()+at+1,uint8_t(v),cost);summary_.appended=true;}else if(width==1)write(base()+at,uint8_t(v),cost);else{write(0x15c2e,uint8_t(v>>8),cost);write(0x15c2f,uint8_t(v),cost);}},[&](unsigned at){return byteClock(base()+at,previous);});
   switch(stage){case S::RetainPart:case S::RetainIndex:case S::RetainScratch:case S::RetainNote:case S::RetainVelocity:case S::DispatchActivity:case S::DispatchMonoReset:case S::DispatchPart:case S::DispatchLivePart:effect_.write=true;break;case S::ReleaseScratch:case S::ReleaseIndex:case S::ReleasePart:case S::ReleaseVelocity:case S::ReleaseNote:case S::Finish:effect_.read=true;break;default:break;}
   if(on_->awaitingActivity()){keys_.emplace(NativeKeyService::Kind::Physical);select(Component::Keys);}else if(on_->awaitingMonoReset()){arp_.emplace(NativeArpResetService::Input{summary_.input.stream});select(Component::ArpReset);}else if(on_->awaitingPart()){lookup_.emplace(PartLookupTask::Layout::Parameters);select(Component::Lookup);}
  }else{using T=NoteOffStateTask;using S=T::Stage;const auto stage=off_->stage();off_->advanceBefore(cost,[&](T::Read f,unsigned at)->uint32_t{return f==T::Read::Note?uint8_t(summary_.input.noteVelocity):read(base()+at,cost-((f==T::Read::HeldByte||f==T::Read::PhysicalByte)?byteClock(base()+at,previous):0));},[&](T::Write,unsigned at,uint8_t v){write(base()+at,v,cost);},[&](unsigned at){return byteClock(base()+at,previous);});
   switch(stage){case S::RetainPart:case S::RetainMap:case S::RetainPedal:case S::RetainIndex:case S::RetainUpper:case S::RetainVoice:case S::RetainData:case S::RetainNote:case S::RetainPatch:case S::DispatchPart:case S::DispatchCompact:case S::DispatchHeld:case S::DispatchRelease:case S::DispatchMonoReset:case S::DispatchPhysicalPart:effect_.write=true;break;case S::ReleasePart:case S::ReleaseMap:case S::ReleasePedal:case S::ReleaseIndex:case S::ReleaseUpper:case S::ReleaseVoice:case S::ReleaseData:case S::ReleaseNote:case S::ReleasePatch:case S::Finish:effect_.read=true;break;default:break;}
   if(off_->awaitingPart()||off_->awaitingPhysicalPart()){lookup_.emplace(PartLookupTask::Layout::Parameters);select(Component::Lookup);}else if(off_->awaitingCompact()){keys_.emplace(NativeKeyService::Kind::Compact,NativeKeyService::Input{summary_.input.noteVelocity,0});select(Component::Keys);}else if(off_->awaitingHeld()){keys_.emplace(NativeKeyService::Kind::Held);select(Component::Keys);}else if(off_->awaitingRelease()){summary_.released=true;voice_.emplace(VoiceReleaseTask::Mode::Part);select(Component::VoiceRelease);}else if(off_->awaitingMonoReset()){internal_.emplace(InternalKeyOutputService::Kind::Release,InternalKeyOutputService::Input{0,summary_.input.noteVelocity});select(Component::InternalRelease);}
  }return cost;
 }
private:
 template<class T>const T*nested()const{switch(component_){case Component::Keys:return keys_->template task<T>();case Component::ArpReset:return arp_->template task<T>();case Component::VoiceRelease:return voice_->template task<T>();case Component::InternalRelease:return internal_->template task<T>();default:return nullptr;}}
 static unsigned byteClock(uint32_t a,int p){return a<0x400000&&!(p&1)&&a==(uint32_t(p)|1u)?0:3;}uint32_t base()const{return 0x160d2u+334*summary_.part;}void select(Component c){component_=c;components_|=1u<<unsigned(c);}
 Kind kind_;Component component_=Component::State;uint32_t components_=1;Effect effect_{};Summary summary_{};std::optional<NoteOnStateTask>on_;std::optional<NoteOffStateTask>off_;std::optional<PartLookupTask>lookup_;std::optional<NativeKeyService>keys_;std::optional<NativeArpResetService>arp_;std::optional<NativeVoiceReleaseService>voice_;std::optional<InternalKeyOutputService>internal_;
};
}
